def _py_tree_collect_candidates() -> list[str]:
    """Walk src2/ and tests/ and return relative .py paths."""
    roots = [REPO_ROOT / 'src2', REPO_ROOT / 'tests']
    candidates: list[str] = []
    for root in roots:
        if not root.is_dir():
            continue
        for path in sorted(root.rglob('*.py')):
            try:
                rel = str(path.relative_to(REPO_ROOT))
            except ValueError:
                continue
            candidates.append(rel)
    return candidates


def _py_tree_filter_ignored(candidates: list[str]) -> list[str]:
    """Remove gitignored paths from the candidate list."""
    try:
        proc = subprocess.run(
            ['git', 'check-ignore', '--stdin', '--no-index'],
            input='\n'.join(candidates),
            capture_output=True,
            text=True,
            cwd=str(REPO_ROOT),
            timeout=30,
        )
        ignored = set(proc.stdout.splitlines())
        return [c for c in candidates if c not in ignored]
    except (subprocess.SubprocessError, OSError):
        return candidates


def _py_tree_render(shown: list[str]) -> str:
    """Render a tree-style listing of relative paths."""
    tree_lines: list[str] = []
    for rel in shown:
        parts = rel.split('/')
        indent = '    ' * (len(parts) - 1)
        tree_lines.append(f'{indent}└── {parts[-1]}')
    return '\n'.join(tree_lines)"}

